SELECT c.id, c.school_id, c.parent_id, c.category_code, c.category_name, c.enabled_status, c.sort_no, c.remark, c.create_time, u.actual_name createUser FROM t_as_course_category c left join t_base_user u on c.create_user = u.id
c.is_valid = 1
AND c.school_id = #{query.schoolId}
AND c.category_name LIKE concat('%', #{query.categoryName}, '%')
AND c.enabled_status = #{query.enabledStatus}
ORDER BY c.sort_no ASC

SELECT c.id, c.school_id, c.parent_id, c.category_code, c.category_name, c.enabled_status, c.sort_no, c.remark, c.create_time, u.actual_name AS createUser FROM t_as_course_category c LEFT JOIN t_base_user u ON c.create_user = u.id
c.is_valid = 1
AND c.school_id = #{query.schoolId}
AND c.category_name LIKE concat('%', #{query.categoryName}, '%')
AND c.enabled_status = #{query.enabledStatus}
ORDER BY c.sort_no ASC, c.id ASC
